#!/usr/bin/env python3
"""Embed the offline single-page dashboard, deterministically (no build service)."""
import gzip
from pathlib import Path

root = Path(__file__).resolve().parent
source = (root / 'web/index.html').read_bytes()
compressed = gzip.compress(source, compresslevel=9, mtime=0)
rows = ['  ' + ','.join(f'0x{x:02x}' for x in compressed[i:i+20]) + ','
        for i in range(0, len(compressed), 20)]
(root / 'siri/DashboardPage.h').write_text(
    '// Generated by firmware/pv-sensing/embed_dashboard.py; edit web/index.html.\n'
    '#pragma once\n#include <Arduino.h>\n'
    'static const uint8_t DASHBOARD_GZIP[] PROGMEM = {\n' + '\n'.join(rows) + '\n};\n')
print(f'Dashboard: {len(source)} source bytes, {len(compressed)} gzip bytes')
